export interface TimelineOptions {
  offset?: number;
  step?: number;
  duration?: number;
  cycles?: number;
  cycleGap?: number;
}

export interface TimelineFrame {
  readonly id: string;
  readonly cycle: number;
  readonly start: number;
  readonly duration: number;
  readonly fromOffset: number;
  readonly toOffset: 0;
  readonly fromOpacity: 0;
  readonly toOpacity: 1;
}

export function buildEntranceTimeline(
  ids: readonly string[],
  options: TimelineOptions = {}
): readonly TimelineFrame[] {
  const seen = new Set<string>();
  for (const id of ids) {
    if (typeof id !== "string" || id.length === 0 || seen.has(id)) {
      throw new RangeError("ids must be non-empty and unique");
    }
    seen.add(id);
  }

  const offset = options.offset ?? 24;
  const step = options.step ?? 100;
  const duration = options.duration ?? 400;
  const cycles = options.cycles ?? 1;
  const cycleGap = options.cycleGap ?? 0;

  for (const value of [offset, step, duration, cycles, cycleGap]) {
    if (!Number.isFinite(value) || value < 0) {
      throw new RangeError("options must be finite and non-negative");
    }
  }
  if (!Number.isInteger(cycles)) throw new RangeError("cycles must be an integer");
  if (ids.length === 0 || cycles === 0) return Object.freeze([]);

  const cycleLength = duration + cycleGap;
  const frames: TimelineFrame[] = [];
  for (let cycle = 0; cycle < cycles; cycle++) {
    for (let index = 0; index < ids.length; index++) {
      frames.push(Object.freeze({
        id: ids[index],
        cycle,
        start: cycle * cycleLength + index * step,
        duration,
        fromOffset: offset,
        toOffset: 0,
        fromOpacity: 0,
        toOpacity: 1
      }));
    }
  }
  return Object.freeze(frames);
}

