import { buildEntranceTimeline } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(Object.is(actual, expected), `${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  equal(JSON.stringify(actual), JSON.stringify(expected), message);
}
function rangeError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const ids = ['first', 'second'];
const defaults: any = buildEntranceTimeline(ids);
ids[0] = 'changed';
deepEqual(defaults, [
  { id: 'first', cycle: 0, start: 0, duration: 400, fromOffset: 24, toOffset: 0, fromOpacity: 0, toOpacity: 1 },
  { id: 'second', cycle: 0, start: 100, duration: 400, fromOffset: 24, toOffset: 0, fromOpacity: 0, toOpacity: 1 }
], 'default timeline values and input order');
assert(Object.isFrozen(defaults), 'timeline array is frozen');
assert(defaults.every(Object.isFrozen), 'timeline frames are frozen');

const custom: any = buildEntranceTimeline(['a', 'b'], { offset: 8, step: 10, duration: 20, cycles: 2, cycleGap: 5 });
deepEqual(custom, [
  { id: 'a', cycle: 0, start: 0, duration: 20, fromOffset: 8, toOffset: 0, fromOpacity: 0, toOpacity: 1 },
  { id: 'b', cycle: 0, start: 10, duration: 20, fromOffset: 8, toOffset: 0, fromOpacity: 0, toOpacity: 1 },
  { id: 'a', cycle: 1, start: 35, duration: 20, fromOffset: 8, toOffset: 0, fromOpacity: 0, toOpacity: 1 },
  { id: 'b', cycle: 1, start: 45, duration: 20, fromOffset: 8, toOffset: 0, fromOpacity: 0, toOpacity: 1 }
], 'cycles use the specified cycle span');

const zeroCycles = buildEntranceTimeline(['a'], { cycles: 0 });
deepEqual(zeroCycles, [], 'zero cycles produce no frames');
assert(Object.isFrozen(zeroCycles), 'zero-cycle output is frozen');
const empty = buildEntranceTimeline([]);
deepEqual(empty, [], 'empty identifiers produce no frames');
assert(Object.isFrozen(empty), 'empty output is frozen');

rangeError(() => buildEntranceTimeline(['']), 'empty identifier is rejected');
rangeError(() => buildEntranceTimeline(['same', 'same']), 'duplicate identifier is rejected');
const numericKeys = ['offset', 'step', 'duration', 'cycles', 'cycleGap'];
for (const key of numericKeys) {
  for (const value of [-1, Number.NaN, Number.POSITIVE_INFINITY]) {
    rangeError(() => buildEntranceTimeline(['x'], { [key]: value } as any), `${key} rejects ${String(value)}`);
  }
}
rangeError(() => buildEntranceTimeline(['x'], { cycles: 1.5 }), 'cycles must be an integer');

